import { useEffect } from 'react';
import { getOrCreatePublicDeviceId } from '../utils/publicDeviceId';

const DEVICE_COOKIE = 'linm-scyk-device';
const COMPANY_COOKIE = 'linm-scyk-company';

function writeCookie(name: string, value: string) {
  document.cookie = `${name}=${encodeURIComponent(value)}; Path=/; SameSite=Lax; Max-Age=86400`;
}

/** Cookies so File BFF PUT (LinImageUpload XHR) can mint guest JWT without Authorization. */
export function useGuestPublicFileSession(companyCode: string) {
  useEffect(() => {
    const code = companyCode.trim().toUpperCase();
    if (!code) return;
    writeCookie(DEVICE_COOKIE, getOrCreatePublicDeviceId());
    writeCookie(COMPANY_COOKIE, code);
  }, [companyCode]);
}
