import type { LinImageUploadApi } from '@linm-soft-org/linm-web-common-components';
import { getOrCreatePublicDeviceId } from '../../utils/publicDeviceId';
import {
  type FileAttachmentResponse,
  type FileCommitRequest,
  type FileInitRequest,
  type FileInitResponse,
} from '../files/endpoint';
import { guestBff, guestBffBlob, guestBffOk } from './guestClient';

export function createGuestFilesClient(companyCode: string): LinImageUploadApi {
  const company = companyCode.trim().toUpperCase();
  const deviceHeaders = () => ({
    'X-Company-Id': company,
    'X-Device-Id': getOrCreatePublicDeviceId(),
  });

  return {
    init: async (input: FileInitRequest): Promise<FileInitResponse> => {
      const res = await guestBff<FileInitResponse>(company, 'POST', '/files/init', input);
      return {
        ...res,
        requiredHeaders: {
          ...res.requiredHeaders,
          ...deviceHeaders(),
        },
      };
    },
    complete: async (uploadId: string, objectKey: string): Promise<void> => {
      await guestBffOk(company, 'POST', '/files/complete', { uploadId, objectKey });
    },
    abort: async (uploadId: string): Promise<void> => {
      await guestBffOk(company, 'POST', '/files/abort', { uploadId });
    },
    getObject: (attachmentId: string) => guestBffBlob(company, `/files/${attachmentId}/object`),
  };
}

export async function guestCommitFile(
  companyCode: string,
  body: FileCommitRequest,
): Promise<FileAttachmentResponse> {
  return guestBff<FileAttachmentResponse>(companyCode.trim().toUpperCase(), 'POST', '/files/commit', body);
}
